import{_ as r,o,c as i,am as l}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"Spring学习_SpringMVC","description":"","frontmatter":{"title":"Spring学习_SpringMVC","excerpt":"Spring学习_SpringMVC","date":"2023-12-05 23:28:41","updated":"2023-12-05 23:28:41"},"headers":[],"relativePath":"框架/框架 Spring家族/Spring学习_SpringMVC.md","filePath":"框架/框架 Spring家族/Spring学习_SpringMVC.md","lastUpdated":null}'),n={name:"框架/框架 Spring家族/Spring学习_SpringMVC.md"};function t(d,e,a,c,s,p){return o(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="_1、什么是springmvc" tabindex="-1">1、什么是SpringMVC <a class="header-anchor" href="#_1、什么是springmvc" aria-label="Permalink to &quot;1、什么是SpringMVC&quot;">​</a></h3><p>SpringMVC是Spring框架中的一个模块，用于构建Web应用程序，采用了经典的MVC设计模式。</p><p>MVC英文是Model View Controller，是模型(model)－视图(view)－控制器(controller)的缩写，一种软件设计规范。本质上也是一种解耦。核心思想是通过将业务逻辑、数据、显示分离来组织代码。</p><ol><li><strong>模型（Model）：</strong><ul><li>模型代表应用程序的业务逻辑和数据。在SpringMVC中，模型通常是一个POJO（Plain Old Java Object）类，负责封装业务数据。</li><li>模型对象存储应用程序的状态，与数据库进行交互，执行业务逻辑等。</li></ul></li><li><strong>视图（View）：</strong><ul><li>视图负责渲染模型数据并展示给用户。在SpringMVC中，视图通常是JSP（JavaServer Pages）或Thymeleaf等模板引擎。</li><li>视图负责将模型的数据以用户友好的方式呈现，与用户进行交互。</li></ul></li><li><strong>控制器（Controller）：</strong><ul><li>控制器接收用户的请求并决定调用哪个业务逻辑处理方法。在SpringMVC中，控制器通常是一个类，使用注解来标识处理请求的方法。</li><li>控制器处理请求后，调用适当的业务逻辑，获取或更新模型数据，然后选择合适的视图来渲染响应。</li></ul></li><li><strong>前端控制器（Front Controller）：</strong><ul><li>SpringMVC 使用DispatcherServlet作为前端控制器，它是Servlet的一个子类，负责拦截所有进入应用的请求。</li><li>DispatcherServlet将请求分发给相应的处理器（Controller），并将模型数据传递给合适的视图进行渲染。</li></ul></li><li><strong>处理器映射器和视图解析器：</strong><ul><li>处理器映射器负责将请求映射到合适的控制器，根据请求URL找到对应的处理器。</li><li>视图解析器负责将逻辑视图名解析为实际的视图对象，决定使用哪个视图来呈现模型数据。</li></ul></li></ol><h3 id="_2、springmvc的核心组件" tabindex="-1">2、SpringMVC的核心组件 <a class="header-anchor" href="#_2、springmvc的核心组件" aria-label="Permalink to &quot;2、SpringMVC的核心组件&quot;">​</a></h3><ul><li><strong><code>DispatcherServlet</code></strong>：<strong>核心的中央处理器</strong>，负责接收请求、分发，并给予客户端响应。</li><li><strong><code>HandlerMapping</code></strong>：<strong>处理器映射器</strong>，根据 URL 去匹配查找能处理的 <code>Handler</code> ，并会将请求涉及到的拦截器和 <code>Handler</code> 一起封装。</li><li><strong><code>HandlerAdapter</code></strong>：<strong>处理器适配器</strong>，根据 <code>HandlerMapping</code> 找到的 <code>Handler</code> ，适配执行对应的 <code>Handler</code>；</li><li><strong><code>Handler</code></strong>：<strong>请求处理器</strong>，处理实际请求的处理器。</li><li><strong><code>ViewResolver</code></strong>：<strong>视图解析器</strong>，根据 <code>Handler</code> 返回的逻辑视图 / 视图，解析并渲染真正的视图，并传递给 <code>DispatcherServlet</code> 响应客户端</li></ul><h3 id="_3、springmvc的工作原理" tabindex="-1">3、SpringMVC的工作原理 <a class="header-anchor" href="#_3、springmvc的工作原理" aria-label="Permalink to &quot;3、SpringMVC的工作原理&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202312061453227.png" alt="image.png"></p><p><strong>流程说明（重要）：</strong></p><ol><li>客户端（浏览器）发送请求， <code>DispatcherServlet</code>拦截请求。</li><li><code>DispatcherServlet</code> 根据请求信息调用 <code>HandlerMapping</code> 。<code>HandlerMapping</code> 根据 URL 去匹配查找能处理的 <code>Handler</code>（也就是我们平常说的 <code>Controller</code> 控制器） ，并会将请求涉及到的拦截器和 <code>Handler</code> 一起封装。</li><li><code>DispatcherServlet</code> 调用 <code>HandlerAdapter</code>适配器执行 <code>Handler</code> 。</li><li><code>Handler</code> 完成对用户请求的处理后，会返回一个 <code>ModelAndView</code> 对象给<code>DispatcherServlet</code>，<code>ModelAndView</code> 顾名思义，包含了数据模型以及相应的视图的信息。<code>Model</code> 是返回的数据对象，<code>View</code> 是个逻辑上的 <code>View</code>。</li><li><code>ViewResolver</code> 会根据逻辑 <code>View</code> 查找实际的 <code>View</code>。</li><li><code>DispaterServlet</code> 把返回的 <code>Model</code> 传给 <code>View</code>（视图渲染）。</li><li>把 <code>View</code> 返回给请求者（浏览器）</li></ol><p>to be contined....</p><hr><p>参考</p><ul><li><a href="https://www.pdai.tech/md/spring/spring-x-framework-springmvc.html" target="_blank" rel="noreferrer">https://www.pdai.tech/md/spring/spring-x-framework-springmvc.html</a></li><li><a href="https://javaguide.cn/system-design/framework/spring/spring-knowledge-and-questions-summary.html#spring-mvc" target="_blank" rel="noreferrer">https://javaguide.cn/system-design/framework/spring/spring-knowledge-and-questions-summary.html#spring-mvc</a></li><li><a href="https://blog.csdn.net/Zhangsama1/article/details/131237139" target="_blank" rel="noreferrer">https://blog.csdn.net/Zhangsama1/article/details/131237139</a></li></ul>',14)])])}const m=r(n,[["render",t]]);export{h as __pageData,m as default};
